23	/// Progress events emitted during workflow execution.
24	#[derive(Debug)]
25	pub enum RunProgress<'a> {
26	    /// A step is about to start.
27	    StepStarting {
28	        name: &'a str,
29	        index: usize,
30	        total: usize,
31	    },
32	    /// A step finished.
33	    StepFinished {
34	        name: &'a str,
35	        result: &'a StepResult,
36	    },
37	    /// A step was skipped.
38	    StepSkipped { name: &'a str },
39	}
40	
41	/// Orchestrates the execution of a workflow.
42	pub struct WorkflowRunner<'a> {
43	    pub(super) config: &'a BivvyConfig,
44	    pub(super) steps: HashMap<String, ResolvedStep>,
45	    pub(super) snapshot_store: SnapshotStore,
46	}
47	
48	/// Result of running a workflow.
49	#[derive(Debug)]
50	pub struct WorkflowResult {
51	    /// Workflow name.
52	    pub workflow: String,
53	    /// Results from each executed step.
54	    pub steps: Vec<StepResult>,
55	    /// Names of skipped steps.
56	    pub skipped: Vec<String>,
57	    /// Total duration.
58	    pub duration: Duration,
59	    /// Whether all steps succeeded.
60	    pub success: bool,
61	    /// Whether the workflow was aborted by the user during recovery.
62	    pub aborted: bool,
63	}
64	
65	/// Options for running a workflow.
66	#[derive(Debug, Default)]
67	pub struct RunOptions {
68	    /// Workflow name (defaults to "default").
69	    pub workflow: Option<String>,
70	    /// Only run these steps.
71	    pub only: HashSet<String>,
72	    /// Skip these steps.
73	    pub skip: HashSet<String>,
74	    /// How to handle skipped step dependencies.
75	    pub skip_behavior: SkipBehavior,
76	    /// Force re-run these steps even if complete.
77	    pub force: HashSet<String>,
78	    /// Force re-run every step in the workflow, bypassing all checks.
79	    pub force_all: bool,
80	    /// Dry run mode.
81	    pub dry_run: bool,
82	    /// Requirements that are provided by the environment and should skip gap checks.
83	    pub provided_requirements: HashSet<String>,
84	    /// Active environment name for only_environments filtering.
85	    pub active_environment: Option<String>,
86	    /// Use the diagnostic funnel pipeline for error recovery.
87	    pub diagnostic_funnel: bool,
88	    /// Discard all persisted satisfaction records and evaluate everything fresh.
89	    pub fresh: bool,
90	}
91	
92	impl RunOptions {
93	    /// Whether the named step should be forced to run, bypassing checks.
94	    ///
95	    /// A step is forced if `force_all` is set, or if its name appears in the
96	    /// `force` set. Step- and workflow-level force directives are merged into
97	    /// these fields by the caller before the runner is invoked.
98	    pub fn should_force(&self, step_name: &str) -> bool {
99	        self.force_all || self.force.contains(step_name)
100	    }
101	}
102	
103	impl<'a> WorkflowRunner<'a> {
104	    /// Create a new workflow runner with an in-memory snapshot store.
105	    pub fn new(config: &'a BivvyConfig, steps: HashMap<String, ResolvedStep>) -> Self {
106	        Self {
107	            config,
108	            steps,
109	            snapshot_store: SnapshotStore::empty(),
110	        }
111	    }
112	
113	    /// Create a new workflow runner with a specific snapshot store.
114	    pub fn with_snapshot_store(
115	        config: &'a BivvyConfig,
116	        steps: HashMap<String, ResolvedStep>,
117	        snapshot_store: SnapshotStore,
118	    ) -> Self {
119	        Self {
120	            config,
121	            steps,
122	            snapshot_store,
123	        }
124	    }
125	
126	    /// Get a mutable reference to the snapshot store (for saving after run).
127	    pub fn snapshot_store_mut(&mut self) -> &mut SnapshotStore {
128	        &mut self.snapshot_store
129	    }
130	
131	    /// Run the specified workflow.
132	    ///
133	    /// `base_env` is the YAML-derived env stack (settings + workflow), already
134	    /// merged in priority order. `process_env` is the parent process
135	    /// environment, which wins over both `base_env` and any step-level env.
136	    #[allow(clippy::too_many_arguments)]
137	    pub fn run(
138	        &mut self,
139	        options: &RunOptions,
140	        context: &InterpolationContext,
141	        base_env: &HashMap<String, String>,
142	        process_env: &HashMap<String, String>,
143	        project_root: &Path,
144	    ) -> Result<WorkflowResult> {
145	        let mut event_bus = EventBus::new();
146	        self.run_with_progress(
147	            options,
148	            context,
149	            base_env,
150	            process_env,
151	            project_root,
152	            None,
153	            None,
154	            |_| {},
155	            &mut event_bus,
156	        )
157	    }
158	
159	    /// Run the specified workflow with a progress callback.
160	    #[allow(clippy::too_many_arguments)]
161	    pub fn run_with_progress(
162	        &mut self,
163	        options: &RunOptions,
164	        context: &InterpolationContext,
165	        base_env: &HashMap<String, String>,
166	        process_env: &HashMap<String, String>,
167	        project_root: &Path,
168	        mut gap_checker: Option<&mut GapChecker<'_>>,
169	        mut state: Option<&mut StateStore>,
170	        mut on_progress: impl FnMut(RunProgress<'_>),
171	        _event_bus: &mut EventBus,
172	    ) -> Result<WorkflowResult> {
173	        let start = Instant::now();
174	        let workflow_name = options.workflow.as_deref().unwrap_or("default");
175	
176	        // Build dependency graph and execution plan
177	        let graph = self.build_graph(workflow_name)?;
178	        let workflow_steps = &self.config.workflows[workflow_name].steps;
179	        let plan = build_execution_plan(&graph, workflow_steps, options, &self.steps)?;
180	
181	        let total = plan.steps_to_run.len();
182	
183	        // Report skipped steps
184	        for skip_name in &plan.flag_skipped {
185	            on_progress(RunProgress::StepSkipped { name: skip_name });
186	        }
187	        for skip_name in &plan.env_skipped {
188	            on_progress(RunProgress::StepSkipped { name: skip_name });
189	        }
190	
191	        let mut results = Vec::new();
192	        let mut all_success = true;
193	        let mut failed_steps: HashSet<String> = HashSet::new();
194	
195	        for (index, step_name) in plan.steps_to_run.iter().enumerate() {
196	            let step =
197	                self.steps
198	                    .get(step_name)
199	                    .ok_or_else(|| BivvyError::ConfigValidationError {
200	                        message: format!("Step '{}' not found in resolved steps", step_name),
201	                    })?;
202	
203	            // Check if any dependency failed
204	            if decision::blocked_by_failure(step, &failed_steps) {
205	                on_progress(RunProgress::StepSkipped { name: step_name });
206	                all_success = false;
207	                failed_steps.insert(step_name.clone());
208	                continue;
209	            }
210	
211	            // Check requirement gaps (non-UI: any blocking gap is an error)
212	            if let Some(ref mut checker) = gap_checker {
213	                let provided = if options.provided_requirements.is_empty() {
214	                    None
215	                } else {
216	                    Some(&options.provided_requirements)
217	                };
218	                let gaps = checker.check_step(step, provided);
219	                let blocking: Vec<_> = gaps
220	                    .iter()
221	                    .filter(|g| !g.status.is_satisfied() && !g.status.can_proceed())
222	                    .collect();
223	                if !blocking.is_empty() {
224	                    let names: Vec<_> = blocking.iter().map(|g| g.requirement.as_str()).collect();
225	                    return Err(BivvyError::RequirementMissing {
226	                        requirement: names.join(", "),
227	                        message: format!(
228	                            "Step '{}' requires: {}. Run 'bivvy lint' for details.",
229	                            step_name,
230	                            names.join(", ")
231	                        ),
232	                    });
233	                }
234	            }
235	
236	            // Evaluate precondition using the new CheckEvaluator (never bypassed by --force)
237	            if let Some(precondition) = step.execution.effective_precondition() {
238	                let mut evaluator =
239	                    CheckEvaluator::new(project_root, context, &mut self.snapshot_store);
240	                let precond_result = evaluator.evaluate(&precondition);
241	                if !precond_result.passed_check() {
242	                    return Err(BivvyError::StepExecutionError {
243	                        step: step_name.clone(),
244	                        message: format!("Precondition failed: {}", precond_result.description),
245	                    });
246	                }
247	            }
248	
249	            // Evaluate completed check using the new CheckEvaluator
250	            if !options.should_force(step_name) && !step.behavior.force {
251	                if let Some(check) = step.execution.effective_check() {
252	                    let config_hash = check.config_hash();
253	                    let mut evaluator =
254	                        CheckEvaluator::new(project_root, context, &mut self.snapshot_store)
255	                            .with_step(step_name, &config_hash)
256	                            .with_workflow(workflow_name);
257	                    let check_result = evaluator.evaluate(&check);
258	                    if check_result.passed_check() {
259	                        let skip_result = StepResult::skipped(step_name, check_result);
260	                        on_progress(RunProgress::StepFinished {
261	                            name: step_name,
262	                            result: &skip_result,
263	                        });
264	                        results.push(skip_result);
265	                        continue;
266	                    }
267	                }
268	            }
269	
270	            on_progress(RunProgress::StepStarting {
271	                name: step_name,
272	                index,
273	                total,
274	            });
275	
276	            let exec_options = ExecutionOptions {
277	                force: options.should_force(step_name) || step.behavior.force,
278	                dry_run: options.dry_run,
279	                capture_output: true,
280	                ..Default::default()
281	            };
282	
283	            let step_start = Instant::now();
284	            let result = match execute_step(
285	                step,
286	                project_root,
287	                context,
288	                base_env,
289	                process_env,
290	                &exec_options,
291	                None,
292	            ) {
293	                Ok(result) => result,
294	                Err(e) => {
295	                    warn!("Step '{}' errored: {}", step_name, e);
296	                    StepResult::failure(step_name, step_start.elapsed(), e.to_string(), None)
297	                }
298	            };
299	
300	            on_progress(RunProgress::StepFinished {
301	                name: step_name,
302	                result: &result,
303	            });
304	
305	            // Record step state if state tracking is available
306	            if let Some(ref mut state_store) = state {
307	                record_step_state(step, step_name, &result, state_store, project_root);
308	            }
309	
310	            let status = result.status();
311	
312	            results.push(result);
313	
314	            if status == StepStatus::Failed {
315	                all_success = false;
316	                if !step.behavior.allow_failure {
317	                    failed_steps.insert(step_name.clone());
318	                }
319	            }
320	        }
321	
322	        let mut all_skipped: Vec<String> = plan.flag_skipped.into_iter().collect();
323	        all_skipped.extend(plan.env_skipped);
324	
325	        Ok(WorkflowResult {
326	            workflow: workflow_name.to_string(),
327	            steps: results,
328	            skipped: all_skipped,
329	            duration: start.elapsed(),
330	            success: all_success,
331	            aborted: false,
332	        })
333	    }
334	
335	    /// Build the dependency graph for the given workflow.
336	    pub fn build_graph(&self, workflow: &str) -> Result<DependencyGraph> {
337	        let workflow_config = self.config.workflows.get(workflow).ok_or_else(|| {
338	            BivvyError::ConfigValidationError {
339	                message: format!("Unknown workflow: {}", workflow),
340	            }
341	        })?;
342	
343	        let mut builder = DependencyGraph::builder();
344	
345	        for step_name in &workflow_config.steps {
346	            let step =
347	                self.steps
348	                    .get(step_name)
349	                    .ok_or_else(|| BivvyError::ConfigValidationError {
350	                        message: format!(
351	                            "Workflow '{}' references unknown step '{}'",
352	                            workflow, step_name
353	                        ),
354	                    })?;
355	
356	            builder = builder.add_step(step_name.clone(), step.depends_on.clone());
357	        }
358	
359	        builder.build()
360	    }
361	}
362	
363	/// Record a step's result in the state store.
364	pub(super) fn record_step_state(
365	    _step: &ResolvedStep,
366	    step_name: &str,
367	    result: &StepResult,
368	    state: &mut StateStore,
369	    _project_root: &Path,
370	) {
371	    let state_status = match result.status() {
372	        StepStatus::Completed => crate::state::StepStatus::Success,
373	        StepStatus::Failed => crate::state::StepStatus::Failed,
374	        StepStatus::Skipped => crate::state::StepStatus::Skipped,
375	        _ => crate::state::StepStatus::NeverRun,
376	    };
377	    state.record_step_result(step_name, state_status, result.duration);
378	}
