1	//! Interactive workflow orchestration.
2	//!
3	//! This module contains the interactive execution loop (`run_with_ui`) — the
4	//! workflow-level coordination layer. Step-level concerns (prompts, execution,
5	//! recovery, error display) are delegated to [`super::step_manager::StepManager`].
6	//!
7	//! Step execution with recovery is in [`super::execution`]. Prompt conversion
8	//! is in [`super::execution::config_prompt_to_ui_prompt`].
9	
10	use std::collections::{HashMap, HashSet};
11	use std::path::Path;
12	use std::time::Instant;
13	
14	use crate::checks::CheckResult;
15	use crate::config::interpolation::InterpolationContext;
16	use crate::config::schema::StepOverride;
17	use crate::error::{BivvyError, Result};
18	use crate::logging::{BivvyEvent, EventBus, StepOutcomeKind};
19	use crate::requirements::checker::GapChecker;
20	use crate::state::satisfaction::{SatisfactionCache, SatisfactionRecord};
21	use crate::state::StateStore;
22	use crate::ui::theme::BivvyTheme;
23	use crate::ui::UserInterface;
24	
25	use super::display::WorkflowDisplay;
26	use super::plan::build_execution_plan;
27	use super::step_manager::{SkipCategory, StepAction, StepExecutionOptions, StepManager};
28	use super::workflow::{RunOptions, WorkflowResult, WorkflowRunner};
29	
30	impl<'a> WorkflowRunner<'a> {
31	    /// Run a workflow with full interactive UI support.
32	    ///
33	    /// This is the primary execution entry point for interactive use. It manages
34	    /// the workflow lifecycle: building the execution plan, iterating over steps,
35	    /// updating the progress bar, tracking workflow state, and recording results.
36	    ///
37	    /// Step-level concerns (check evaluation, prompts, execution, recovery) are
38	    /// delegated to [`StepManager`].
39	    #[allow(clippy::too_many_arguments)]
40	    pub fn run_with_ui(
41	        &mut self,
42	        options: &RunOptions,
43	        context: &InterpolationContext,
44	        base_env: &HashMap<String, String>,
45	        process_env: &HashMap<String, String>,
46	        project_root: &Path,
47	        workflow_non_interactive: bool,
48	        step_overrides: &HashMap<String, StepOverride>,
49	        mut gap_checker: Option<&mut GapChecker<'_>>,
50	        state: Option<&mut StateStore>,
51	        satisfaction_cache: &mut SatisfactionCache,
52	        ui: &mut dyn UserInterface,
53	        workflow_display: &mut dyn WorkflowDisplay,
54	        event_bus: &mut EventBus,
55	    ) -> Result<WorkflowResult> {
56	        let start = Instant::now();
57	        let workflow_name = options.workflow.as_deref().unwrap_or("default");
58	        let mut context = context.clone();
59	
60	        // Topological sort: compute execution order from the dependency graph.
61	        let graph = self.build_graph(workflow_name)?;
62	        let workflow_steps = &self.config.workflows[workflow_name].steps;
63	        // Pre-filter: remove steps excluded by --skip flags or only_environments mismatch.
64	        let plan = build_execution_plan(&graph, workflow_steps, options, &self.steps)?;
65	
66	        let total = plan.steps_to_run.len();
67	        let theme = BivvyTheme::new();
68	
69	        // Emit workflow started
70	        event_bus.emit(&BivvyEvent::WorkflowStarted {
71	            name: workflow_name.to_string(),
72	            step_count: total,
73	        });
74	
75	        // Report pre-filtered steps before the loop begins.
76	        for skip_name in &plan.flag_skipped {
77	            event_bus.emit(&BivvyEvent::StepFilteredOut {
78	                name: skip_name.clone(),
79	                reason: "skip_flag".to_string(),
80	            });
81	            event_bus.emit(&BivvyEvent::StepOutcome {
82	                name: skip_name.clone(),
83	                outcome: StepOutcomeKind::FilteredOut,
84	                detail: Some("skip_flag".to_string()),
85	                duration_ms: None,
86	            });
87	            ui.message(&format!(
88	                "    {}",
89	                theme.format_skipped(&format!("{} skipped", skip_name))
90	            ));
91	        }
92	        for skip_name in &plan.env_skipped {
93	            event_bus.emit(&BivvyEvent::StepFilteredOut {
94	                name: skip_name.clone(),
95	                reason: "environment".to_string(),
96	            });
97	            let env_label = options.active_environment.as_deref().unwrap_or("unknown");
98	            event_bus.emit(&BivvyEvent::StepOutcome {
99	                name: skip_name.clone(),
100	                outcome: StepOutcomeKind::FilteredOut,
101	                detail: Some(format!("not in {} environment", env_label)),
102	                duration_ms: None,
103	            });
104	            ui.message(&format!(
105	                "    {}",
106	                theme.format_skipped(&format!(
107	                    "{} skipped (not in {} environment)",
108	                    skip_name, env_label
109	                ))
110	            ));
111	        }
112	
113	        let interactive = ui.is_interactive() && !workflow_non_interactive;
114	
115	        let mut results = Vec::new();
116	        let mut all_success = true;
117	        let mut failed_steps: HashSet<String> = HashSet::new();
118	        let mut user_skipped_steps: HashSet<String> = HashSet::new();
119	        let mut satisfied_steps: HashSet<String> = HashSet::new();
120	        let mut named_check_results: HashMap<String, CheckResult> = HashMap::new();
121	        let mut workflow_aborted = false;
122	
123	        // Initialize the persistent progress bar (pinned at terminal bottom).
124	        workflow_display.start_progress(total);
125	
126	        for (index, step_name) in plan.steps_to_run.iter().enumerate() {
127	            let step =
128	                &self
129	                    .steps
130	                    .get(step_name)
131	                    .ok_or_else(|| BivvyError::ConfigValidationError {
132	                        message: format!("Step '{}' not found in resolved steps", step_name),
133	                    })?;
134	
135	            // Update progress bar immediately — before execution, so the user
136	            // sees "Step N/M" the moment iteration reaches this step.
137	            workflow_display.update_progress(index + 1, total, start.elapsed());
138	
139	            // Hand off to the step display for this iteration.
140	            let mut step_display = workflow_display.begin_step(index, total);
141	
142	            // Create StepManager and delegate step-level execution
143	            let step_mgr = StepManager::new(step, step_name, index, total, &theme);
144	
145	            let exec_opts = StepExecutionOptions {
146	                dry_run: options.dry_run,
147	                interactive,
148	                diagnostic_funnel: options.diagnostic_funnel,
149	                project_root,
150	                base_env,
151	                process_env,
152	                force_steps: &options.force,
153	                force_all: options.force_all,
154	                provided_requirements: &options.provided_requirements,
155	            };
156	
157	            let action = step_mgr.execute(
158	                &exec_opts,
159	                &mut context,
160	                step_overrides,
161	                &mut gap_checker,
162	                &mut self.snapshot_store,
163	                &self.steps,
164	                state.as_deref(),
165	                satisfaction_cache,
166	                &failed_steps,
167	                &user_skipped_steps,
168	                &satisfied_steps,
169	                &mut named_check_results,
170	                &results,
171	                ui,
172	                step_display.as_mut(),
173	                event_bus,
174	            )?;
175	
176	            // Update workflow state based on step action.
177	            // The workflow only tracks aggregate state (satisfied/failed/skipped sets)
178	            // — all per-step decisions are made by StepManager via the decision engine.
179	            match action {
180	                StepAction::Completed(result) => {
181	                    satisfied_steps.insert(step_name.clone());
182	
183	                    // Record successful execution in satisfaction cache
184	                    let record = SatisfactionRecord {
185	                        satisfied: true,
186	                        source: crate::state::satisfaction::SatisfactionSource::ExecutionHistory,
187	                        recorded_at: chrono::Utc::now(),
188	                        evidence: crate::state::satisfaction::SatisfactionEvidence::HistoricalRun {
189	                            ran_at: chrono::Utc::now(),
190	                            exit_code: result.exit_code.unwrap_or(0),
191	                        },
192	                        config_hash: None,
193	                        step_hash: None,
194	                    };
195	                    satisfaction_cache.store(step_name, record);
196	
197	                    results.push(result);
198	                }
199	
200	                StepAction::Skipped(result, category) => {
201	                    // StepManager classifies the skip reason so the workflow
202	                    // doesn't need to inspect StepResult internals.
203	                    match category {
204	                        SkipCategory::Satisfied => {
205	                            satisfied_steps.insert(step_name.clone());
206	                        }
207	                        SkipCategory::UserDeclined | SkipCategory::DependencySkipped => {
208	                            user_skipped_steps.insert(step_name.clone());
209	                        }
210	                        SkipCategory::RecoverySkipped | SkipCategory::Other => {
211	                            // Recovery-skipped steps do NOT block dependents —
212	                            // the user chose to move past the failure.
213	                        }
214	                    }
215	                    results.push(result);
216	                }
217	
218	                StepAction::Failed(result) => {
219	                    all_success = false;
220	                    if !step.behavior.allow_failure {
221	                        failed_steps.insert(step_name.clone());
222	                    }
223	                    results.push(result);
224	                }
225	
226	                StepAction::Blocked => {
227	                    all_success = false;
228	                    failed_steps.insert(step_name.clone());
229	                }
230	
231	                StepAction::Aborted(result) => {
232	                    results.push(result);
233	                    workflow_aborted = true;
234	                    all_success = false;
235	                    break;
236	                }
237	            }
238	
239	            // Update progress bar after step completes (reflects final position)
240	            workflow_display.update_progress(index + 1, total, start.elapsed());
241	        }
242	
243	        // Flush satisfaction cache to disk
244	        if !options.dry_run {
245	            if let Err(e) = satisfaction_cache.flush() {
246	                tracing::warn!("Failed to flush satisfaction cache: {}", e);
247	            }
248	        }
249	
250	        // Finish progress bar (clear before summary)
251	        workflow_display.finish_progress();
252	
253	        let mut all_skipped: Vec<String> = plan.flag_skipped.into_iter().collect();
254	        all_skipped.extend(plan.env_skipped);
255	
256	        let steps_run = results.len();
257	        let steps_skipped_count = all_skipped.len();
258	        let duration = start.elapsed();
259	
260	        event_bus.emit(&BivvyEvent::WorkflowCompleted {
261	            name: workflow_name.to_string(),
262	            success: all_success,
263	            aborted: workflow_aborted,
264	            steps_run,
265	            steps_skipped: steps_skipped_count,
266	            duration_ms: duration.as_millis() as u64,
267	        });
268	
269	        Ok(WorkflowResult {
270	            workflow: workflow_name.to_string(),
271	            steps: results,
272	            skipped: all_skipped,
273	            duration,
274	            success: all_success,
275	            aborted: workflow_aborted,
276	        })
277	    }
278	}
