644	    /// Handle a prompt decision. Returns `Some(StepAction)` if the step should
645	    /// not proceed to execution (user declined), or `None` to fall through.
646	    #[allow(clippy::too_many_arguments)]
647	    fn handle_prompt(
648	        &self,
649	        prompt_key: &str,
650	        eval_result: &EvaluationResult,
651	        step_pad: &str,
652	        _needs_force: bool,
653	        event_bus: &mut EventBus,
654	        ui: &mut dyn UserInterface,
655	        step_display: &mut dyn StepDisplay,
656	    ) -> Result<Option<StepAction>> {
657	        if prompt_key.starts_with("rerun_") {
658	            let prompt_text = format!("{}. Run again?", eval_result.reason);
659	            let prompt = Prompt {
660	                key: prompt_key.to_string(),
661	                question: format!("{}{}", step_pad, prompt_text),
662	                prompt_type: PromptType::Select {
663	                    options: vec![
664	                        PromptOption {
665	                            label: "No  (n)".to_string(),
666	                            value: "no".to_string(),
667	                        },
668	                        PromptOption {
669	                            label: "Yes (y)".to_string(),
670	                            value: "yes".to_string(),
671	                        },
672	                    ],
673	                },
674	                default: Some("no".to_string()),
675	            };
676	            let answer = ui.prompt(&prompt)?;
677	            // clear_lines removed — surface tracks regions
678	            if answer.as_string() != "yes" {
679	                event_bus.emit(&BivvyEvent::StepSkipped {
680	                    name: self.step_name.to_string(),
681	                    reason: eval_result.reason.clone(),
682	                });
683	                event_bus.emit(&BivvyEvent::StepOutcome {
684	                    name: self.step_name.to_string(),
685	                    outcome: StepOutcomeKind::Satisfied,
686	                    detail: Some(eval_result.reason.clone()),
687	                    duration_ms: None,
688	                });
689	                let skip_label = crate::ui::satisfaction_label(&eval_result.reason);
690	                step_display.message(&format!(
691	                    "{}{}",
692	                    step_pad,
693	                    StatusKind::Success.format(self.theme, &skip_label)
694	                ));
695	                return Ok(Some(StepAction::Skipped(
696	                    StepResult::check_passed(
697	                        &self.step.name,
698	                        CheckResult::passed(eval_result.reason.clone()),
699	                    ),
700	                    SkipCategory::Satisfied,
701	                )));
702	            }
703	            // User chose yes — fall through to execution
704	        } else if prompt_key.starts_with("autorun_") {
705	            let prompt_text = format!("Run {}?", self.step.title);
706	            let prompt = Prompt {
707	                key: prompt_key.to_string(),
708	                question: format!("{}{}", step_pad, prompt_text),
709	                prompt_type: PromptType::Select {
710	                    options: vec![
711	                        PromptOption {
712	                            label: "Yes (y)".to_string(),
713	                            value: "yes".to_string(),
714	                        },
715	                        PromptOption {
716	                            label: "No  (n)".to_string(),
717	                            value: "no".to_string(),
718	                        },
719	                    ],
720	                },
721	                default: Some("yes".to_string()),
722	            };
723	            event_bus.emit(&BivvyEvent::UserPrompted {
724	                step: Some(self.step_name.to_string()),
725	                prompt: prompt_text,
726	                options: vec!["Yes (y)".to_string(), "No  (n)".to_string()],
727	            });
728	            let answer = ui.prompt(&prompt)?;
729	            let answer_str = answer.as_string();
730	            event_bus.emit(&BivvyEvent::UserResponded {
731	                step: Some(self.step_name.to_string()),
732	                input: answer_str.clone(),
733	                method: crate::logging::InputMethod::ArrowSelect,
734	            });
735	            if answer_str != "yes" {
736	                // clear_lines removed — surface tracks regions
737	                event_bus.emit(&BivvyEvent::StepDecided {
738	                    name: self.step_name.to_string(),
