1	//! Mock UI implementation for testing.
2	//!
3	//! `MockUI` implements the `UserInterface` trait and captures all
4	//! interactions for later assertion. It can be configured with
5	//! pre-determined prompt responses.
6	//!
7	//! # Example
8	//!
9	//! ```
10	//! use bivvy::ui::{MockUI, OutputMode, OutputWriter, Prompt, PromptType};
11	//!
12	//! let mut ui = MockUI::new();
13	//! ui.set_prompt_response("db_name", "myapp_dev");
14	//!
15	//! // Use ui in code under test...
16	//! ui.message("Starting setup");
17	//! ui.success("Done!");
18	//!
19	//! // Assert on captured interactions
20	//! assert!(ui.messages().contains(&"Starting setup".to_string()));
21	//! assert!(ui.successes().contains(&"Done!".to_string()));
22	//! ```
23	
24	use std::collections::{HashMap, VecDeque};
25	
26	use crate::error::Result;
27	
28	use super::{
29	    OutputMode, OutputWriter, ProgressDisplay, Prompt, PromptResult, PromptType, Prompter,
30	    SpinnerFactory, SpinnerHandle, UiState,
31	};
32	
33	/// Mock UI implementation for testing.
34	///
35	/// Captures all UI interactions and allows pre-configured prompt responses.
36	/// Supports both single responses (via `set_prompt_response`) and queued
37	/// responses (via `queue_prompt_responses`) for keys called multiple times.
38	#[derive(Debug, Default)]
39	pub struct MockUI {
40	    mode: OutputMode,
41	    interactive: bool,
42	    messages: Vec<String>,
43	    successes: Vec<String>,
44	    warnings: Vec<String>,
45	    errors: Vec<String>,
46	    headers: Vec<String>,
47	    hints: Vec<String>,
48	    progress: Vec<(usize, usize)>,
49	    spinners: Vec<String>,
50	    error_blocks: Vec<(String, String, Option<String>, usize)>,
51	    prompt_responses: HashMap<String, String>,
52	    prompt_queues: HashMap<String, VecDeque<String>>,
53	    prompts_shown: Vec<String>,
54	    /// Fallback response for any prompt key not in `prompt_responses` or `prompt_queues`.
55	    default_prompt_response: Option<String>,
56	}
57	
58	impl MockUI {
59	    /// Create a new MockUI with Normal output mode.
60	    pub fn new() -> Self {
61	        Self {
62	            mode: OutputMode::Normal,
63	            ..Default::default()
64	        }
65	    }
66	
67	    /// Create a new MockUI with a specific output mode.
68	    pub fn with_mode(mode: OutputMode) -> Self {
69	        Self {
70	            mode,
71	            ..Default::default()
72	        }
73	    }
74	
75	    /// Set a response for a prompt key.
76	    ///
77	    /// When `prompt()` is called with this key, it returns the configured response.
78	    pub fn set_prompt_response(&mut self, key: &str, response: &str) {
79	        self.prompt_responses
80	            .insert(key.to_string(), response.to_string());
81	    }
82	
83	    /// Set multiple prompt responses at once.
84	    pub fn with_prompt_responses(mut self, responses: HashMap<String, String>) -> Self {
85	        self.prompt_responses = responses;
86	        self
87	    }
88	
89	    /// Queue multiple responses for the same prompt key.
90	    ///
91	    /// Responses are returned in order. After the queue is exhausted,
92	    /// falls back to `set_prompt_response` or defaults.
93	    pub fn queue_prompt_responses(&mut self, key: &str, responses: Vec<&str>) {
94	        let queue = responses.into_iter().map(|s| s.to_string()).collect();
95	        self.prompt_queues.insert(key.to_string(), queue);
96	    }
97	
98	    /// Set a default response for any prompt key not explicitly configured.
99	    ///
100	    /// Useful when a workflow may prompt with unpredictable keys (e.g., recovery
101	    /// prompts whose key includes the step name, which depends on template detection).
102	    pub fn set_default_prompt_response(&mut self, response: &str) {
103	        self.default_prompt_response = Some(response.to_string());
104	    }
105	
106	    /// Set whether this mock behaves as interactive.
107	    pub fn set_interactive(&mut self, interactive: bool) {
108	        self.interactive = interactive;
109	    }
110	
111	    /// Get all captured messages.
112	    pub fn messages(&self) -> &[String] {
113	        &self.messages
114	    }
115	
116	    /// Get all captured success messages.
117	    pub fn successes(&self) -> &[String] {
118	        &self.successes
119	    }
120	
121	    /// Get all captured warning messages.
122	    pub fn warnings(&self) -> &[String] {
123	        &self.warnings
124	    }
125	
126	    /// Get all captured error messages.
127	    pub fn errors(&self) -> &[String] {
128	        &self.errors
129	    }
130	
131	    /// Get all captured headers.
132	    pub fn headers(&self) -> &[String] {
133	        &self.headers
134	    }
135	
136	    /// Get all captured hints.
137	    pub fn hints(&self) -> &[String] {
138	        &self.hints
139	    }
140	
141	    /// Get all captured progress updates.
142	    pub fn progress(&self) -> &[(usize, usize)] {
143	        &self.progress
144	    }
145	
146	    /// Get all spinner messages that were started.
147	    pub fn spinners(&self) -> &[String] {
148	        &self.spinners
149	    }
150	
151	    /// Get all prompts that were shown (by key).
152	    pub fn prompts_shown(&self) -> &[String] {
153	        &self.prompts_shown
154	    }
155	
156	    /// Check if a specific message was shown.
157	    pub fn has_message(&self, msg: &str) -> bool {
158	        self.messages.iter().any(|m| m.contains(msg))
159	    }
160	
161	    /// Check if a specific success was shown.
162	    pub fn has_success(&self, msg: &str) -> bool {
163	        self.successes.iter().any(|m| m.contains(msg))
164	    }
165	
166	    /// Check if a specific error was shown.
167	    pub fn has_error(&self, msg: &str) -> bool {
168	        self.errors.iter().any(|m| m.contains(msg))
169	    }
170	
171	    /// Check if a specific hint was shown.
172	    pub fn has_hint(&self, msg: &str) -> bool {
173	        self.hints.iter().any(|m| m.contains(msg))
174	    }
175	
176	    /// Check if a specific warning was shown.
177	    pub fn has_warning(&self, msg: &str) -> bool {
178	        self.warnings.iter().any(|m| m.contains(msg))
179	    }
180	
181	    /// Get all captured error blocks as (command, output, hint, indent).
182	    pub fn error_blocks(&self) -> &[(String, String, Option<String>, usize)] {
183	        &self.error_blocks
184	    }
185	
186	    /// Clear all captured interactions.
187	    pub fn clear(&mut self) {
188	        self.messages.clear();
189	        self.successes.clear();
190	        self.warnings.clear();
191	        self.errors.clear();
192	        self.headers.clear();
193	        self.hints.clear();
194	        self.progress.clear();
195	        self.spinners.clear();
196	        self.error_blocks.clear();
197	        self.prompts_shown.clear();
198	    }
199	}
200	
201	impl OutputWriter for MockUI {
202	    fn message(&mut self, msg: &str) {
203	        self.messages.push(msg.to_string());
204	    }
205	
206	    fn success(&mut self, msg: &str) {
207	        self.successes.push(msg.to_string());
208	    }
209	
210	    fn warning(&mut self, msg: &str) {
211	        self.warnings.push(msg.to_string());
212	    }
213	
214	    fn error(&mut self, msg: &str) {
215	        self.errors.push(msg.to_string());
216	    }
217	
218	    fn show_hint(&mut self, hint: &str) {
219	        self.hints.push(hint.to_string());
220	    }
221	
222	    fn show_error_block(&mut self, command: &str, output: &str, hint: Option<&str>, indent: usize) {
223	        self.error_blocks.push((
224	            command.to_string(),
225	            output.to_string(),
226	            hint.map(|h| h.to_string()),
227	            indent,
228	        ));
229	        self.errors.push(command.to_string());
230	        if !output.is_empty() {
231	            self.messages.push(output.to_string());
232	        }
233	        if let Some(h) = hint {
234	            self.hints.push(h.to_string());
235	        }
236	    }
237	}
238	
239	impl Prompter for MockUI {
240	    fn prompt(&mut self, prompt: &Prompt) -> Result<PromptResult> {
241	        self.prompts_shown.push(prompt.key.clone());
242	
243	        let is_confirm = matches!(prompt.prompt_type, PromptType::Confirm);
244	        let is_multiselect = matches!(prompt.prompt_type, PromptType::MultiSelect { .. });
245	
246	        // Check queued responses first (for keys called multiple times)
247	        if let Some(queue) = self.prompt_queues.get_mut(&prompt.key) {
248	            if let Some(response) = queue.pop_front() {
249	                if is_confirm {
250	                    let val = matches!(response.as_str(), "true" | "yes" | "y" | "1");
251	                    return Ok(PromptResult::Bool(val));
252	                }
253	                if is_multiselect {
254	                    let values: Vec<String> =
255	                        response.split(',').map(|s| s.trim().to_string()).collect();
256	                    return Ok(PromptResult::Strings(values));
257	                }
258	                return Ok(PromptResult::String(response));
259	            }
260	        }
261	
262	        // Return pre-configured response if available
263	        if let Some(response) = self.prompt_responses.get(&prompt.key) {
264	            if is_confirm {
265	                let val = matches!(response.as_str(), "true" | "yes" | "y" | "1");
266	                return Ok(PromptResult::Bool(val));
267	            }
268	            if is_multiselect {
269	                let values: Vec<String> =
270	                    response.split(',').map(|s| s.trim().to_string()).collect();
271	                return Ok(PromptResult::Strings(values));
272	            }
273	            return Ok(PromptResult::String(response.clone()));
274	        }
275	
276	        // Fall back to default_prompt_response if set (before prompt.default)
277	        if let Some(ref response) = self.default_prompt_response {
278	            if is_confirm {
279	                let val = matches!(response.as_str(), "true" | "yes" | "y" | "1");
280	                return Ok(PromptResult::Bool(val));
281	            }
282	            if is_multiselect {
283	                let values: Vec<String> =
284	                    response.split(',').map(|s| s.trim().to_string()).collect();
285	                return Ok(PromptResult::Strings(values));
286	            }
287	            return Ok(PromptResult::String(response.clone()));
288	        }
289	
290	        // Fall back to default if available
291	        if let Some(default) = &prompt.default {
292	            if is_confirm {
293	                let val = matches!(default.as_str(), "true" | "yes" | "y" | "1");
294	                return Ok(PromptResult::Bool(val));
295	            }
296	            if is_multiselect {
297	                let values: Vec<String> =
298	                    default.split(',').map(|s| s.trim().to_string()).collect();
299	                return Ok(PromptResult::Strings(values));
300	            }
301	            return Ok(PromptResult::String(default.clone()));
302	        }
303	
304	        // Return type-appropriate empty for last resort (for testing)
305	        if is_confirm {
306	            return Ok(PromptResult::Bool(false));
307	        }
308	        if is_multiselect {
309	            return Ok(PromptResult::Strings(Vec::new()));
310	        }
311	        Ok(PromptResult::String(String::new()))
312	    }
313	}
