/// Interactive per-step display backed by a [`TerminalSurface`].
///
/// Prompting and spinner creation are delegated to injected trait
/// objects ([`PromptRenderer`] and [`ProgressBarFactory`]) so the
/// runner module never calls concrete UI functions directly.
pub struct TerminalStepDisplay {
    surface: Arc<TerminalSurface>,
    theme: BivvyTheme,
    mode: OutputMode,
    step_number: String,
    step_indent: usize,
    region: Option<TransientRegion>,
    /// Ring-buffer of recent live-output lines for the spinner tail.
    tail: VecDeque<String>,
    /// Spinner base message — preserved so live-output updates don't
    /// drop the "Running ..." prefix.
    base_message: String,
    /// Maximum tail capacity (depends on output mode).
    tail_capacity: usize,
    /// Injected prompt renderer — keeps terminal/dialoguer coupling out
    /// of the runner module.
    prompt_renderer: Box<dyn PromptRenderer>,
    /// Injected progress bar factory — keeps indicatif styling out of
    /// the runner module.
    bar_factory: Box<dyn ProgressBarFactory>,
}

impl TerminalStepDisplay {
    /// Construct a new terminal step display.
    ///
    /// `prompt_renderer` handles interactive prompts and
    /// `bar_factory` creates configured progress bars, keeping
    /// terminal-crate details out of the runner layer.
    pub fn new(
        surface: Arc<TerminalSurface>,
        mode: OutputMode,
        index: usize,
        total: usize,
        prompt_renderer: Box<dyn PromptRenderer>,
        bar_factory: Box<dyn ProgressBarFactory>,
    ) -> Self {
        let theme = if crate::ui::should_use_colors() {
            BivvyTheme::new()
        } else {
            BivvyTheme::plain()
        };
        let step_number = format!("[{}/{}]", index + 1, total);
        let step_indent = step_number.chars().count() + 1;
        Self {
            surface,
            theme,
            mode,
            step_number,
            step_indent,
            region: None,
            tail: VecDeque::new(),
            base_message: String::new(),
            tail_capacity: live_tail_capacity(mode),
            prompt_renderer,
            bar_factory,
        }
    }

