/// Low-level prompt rendering.
///
/// Unlike [`Prompter`], which manages mutable UI state (cursor
/// coordination, surface pausing), a `PromptRenderer` is a stateless
/// renderer that turns a [`Prompt`] into a [`PromptResult`]. Inject
/// it into display types so the runner module never calls concrete
/// prompt functions directly.
pub trait PromptRenderer {
    /// Render a prompt and return the user's response.
    fn render(&self, prompt: &Prompt) -> Result<PromptResult>;
}

/// Factory for creating [`indicatif::ProgressBar`] instances.
///
/// Abstracts spinner and progress bar creation so the runner's display
/// layer never configures `indicatif` styles directly. Inject a
/// [`TerminalProgressBarFactory`](spinner::TerminalProgressBarFactory)
/// for real terminal output or a
/// [`HiddenProgressBarFactory`](spinner::HiddenProgressBarFactory) for
/// tests.
pub trait ProgressBarFactory {
    /// Create a step-level spinner with the given prefix indentation
    /// and initial message.
    fn create_step_spinner(&self, prefix: &str, message: &str) -> ProgressBar;

    /// Create a workflow-level progress bar for tracking overall
    /// step completion.
    fn create_workflow_bar(&self, total: u64, message: String) -> ProgressBar;
}

