                    Some("exit code 1"),
                    Some(500),
                ),
                workflow_completed(false, 1, 0),
            ],
        );
        let run = parse_log_file(&log_file).unwrap();
        assert_eq!(run.steps[0].outcome_kind(), Some(StepOutcomeKind::Failed));
        assert_eq!(run.error.as_deref(), Some("exit code 1"));
    }

